mapper.insert:
INSERT INTO USER_RANGE_ORGAN
(
RELATION_ID, ORGAN_ID, USER_ID, USERL_ID, GROUP_ID, POSITION_ID, DEPT_ID, FOREIGN_ID, IS_MEMBER, TYPE, POWER, IS_DEF, DEL_FLAG, STATUS, CREATOR_ID, CREATE_TIME, UPDATOR_ID, UPDATE_TIME, SPARE1, SPARE2
)
VALUES
(
#{id}, #{organId}, #{userId}, #{userlId}, #{groupId}, #{positionId}, #{deptId}, #{foreignId}, #{isMember}, #{type}, #{power}, #{isDef}, #{delFlag}, #{status}, #{creatorId}, #{createTime}, #{updatorId}, #{updateTime}, #{spare1}, #{spare2}
)

mapper.update:
UPDATE USER_RANGE_ORGAN
ORGAN_ID = #{organId}, USER_ID = #{userId}, USERL_ID = #{userlId}, GROUP_ID = #{groupId}, POSITION_ID = #{positionId}, DEPT_ID = #{deptId}, FOREIGN_ID = #{foreignId}, IS_MEMBER = #{isMember}, TYPE = #{type}, POWER = #{power}, IS_DEF = #{isDef}, DEL_FLAG = #{delFlag}, STATUS = #{status}, CREATOR_ID = #{creatorId}, CREATE_TIME = #{createTime}, UPDATOR_ID = #{updatorId}, UPDATE_TIME = #{updateTime}, SPARE1 = #{spare1}, SPARE2 = #{spare2}
WHERE RELATION_ID = #{id}

