mapper.select:
SELECT B.*
FROM





                (select B.NICK_NAME as name,B.MEMBER_ID AS memberId ,bu.mobile as mobile ,SPU.RELATION_ID,SPU.IS_DEF,SPU.TYPE,B.USER_ID
                from THIRD_MEMBER B
                left join USER_RANGE_ORGAN SPU on B.MEMBER_ID = SPU.USERL_ID
                and SPU.DEL_FLAG =0

                    and SPU.POSITION_ID = #{bindPositionId}


                WHERE 1 = 1

                ORDER BY B.CREATE_TIME DESC
                ) B
                LIMIT #{offset}, #{limit}


                ( SELECT ROW_NUMBER() OVER (

                ) AS RN, A.* FROM (
                select B.NAME as name,B.MEMBER_ID AS memberId ,bu.mobile as mobile ,SPU.RELATION_ID,SPU.IS_DEF,SPU.TYPE,B.USER_ID
                from THIRD_MEMBER B
                left join USER_RANGE_ORGAN SPU on B.MEMBER_ID = SPU.USERL_ID
                and SPU.DEL_FLAG =0

                    and SPU.POSITION_ID = #{bindPositionId}


                WHERE 1 = 1

                ) A ) B
                 where RN <= (#{offset} + #{limit}) AND RN > #{offset} 




        (select B.NAME as name,B.MEMBER_ID AS memberId ,bu.mobile as mobile ,SPU.RELATION_ID,SPU.IS_DEF,SPU.TYPE,B.USER_ID
        from THIRD_MEMBER B
        left join USER_RANGE_ORGAN SPU on B.MEMBER_ID = SPU.USERL_ID
        and SPU.DEL_FLAG =0

            and SPU.POSITION_ID = #{bindPositionId}


        WHERE 1 = 1

        ORDER BY B.CREATE_TIME DESC
        ) B

