and F.POSITION_ID = #{bindPositionId}
WHERE 1 = 1

SELECT bue.USER_ID,bue.ID_NAME AS NAME,bue.ID_MOBILE AS MOBILE, B.POSITION_ID,B.ORGAN_ID,org.NAME AS ORGAN_NAME FROM USER_RANGE_ORGAN B LEFT JOIN BASE_USER_EXT bue ON B.USER_ID = bue.USER_ID LEFT JOIN BASE_ORGAN org ON B.ORGAN_ID = org.ORGAN_ID WHERE 1=1 AND bue.ID_NAME IS NOT NULL
AND B.POSITION_ID = #{positionId}
AND B.ORGAN_ID = #{organId}
AND (bue.ID_NAME LIKE concat('%',concat(#{key},'%')) OR bue.ID_MOBILE LIKE concat('%',concat(#{key},'%')))

SELECT DISTINCT bue.USER_ID,tm.MEMBER_ID,bue.ID_NAME AS NAME,bue.ID_MOBILE AS MOBILE FROM USER_RANGE_ORGAN B LEFT JOIN THIRD_MEMBER tm ON B.USER_ID = tm.USER_ID LEFT JOIN BASE_USER_EXT bue ON B.USER_ID = bue.USER_ID WHERE 1=1
AND B.GROUP_ID = #{groupId}
AND B.ORGAN_ID IN (SELECT ORGAN_ID FROM ORGAN_WORK WHERE WL_TYPE LIKE '%DYJG%' AND AREA_ID = #{areaId})
AND B.ORGAN_ID IN (SELECT ORGAN_ID FROM ORGAN_WORK WHERE WL_TYPE LIKE '%DYJG%' AND AREA_ID LIKE concat('%',concat(#{areaIdLike},'%')) )
AND B.ORGAN_ID = #{organId}
AND (bue.ID_NAME LIKE concat('%',concat(#{key},'%')) OR bue.ID_MOBILE LIKE concat('%',concat(#{key},'%')))

SELECT DISTINCT bue.USER_ID,tm.MEMBER_ID,bue.ID_NAME AS NAME,bue.ID_MOBILE AS MOBILE FROM USER_RANGE_ORGAN B LEFT JOIN THIRD_MEMBER tm ON B.USER_ID = MU.USER_ID LEFT JOIN BASE_USER_EXT bue ON B.USER_ID = bue.USER_ID WHERE 1=1 AND B.ORGAN_ID = #{organId}
AND B.POSITION_ID IN
#{item}
AND (bue.ID_NAME LIKE concat('%',concat(#{q},'%')) OR bu.MOBILE LIKE concat('%',concat(#{q},'%')))

SELECT DISTINCT bue.USER_ID,bue.ID_NAME AS NAME,bue.ID_MOBILE AS MOBILE,
B.POSITION_ID,B.GROUP_ID,B.ORGAN_ID,org.NAME AS ORGAN_NAME
FROM USER_RANGE_ORGAN B
LEFT JOIN BASE_USER_EXT bue ON B.USER_ID = bue.USER_ID
LEFT JOIN BASE_ORGAN org ON B.ORGAN_ID = org.ORGAN_ID
WHERE 1=1 AND B.DEL_FLAG=0

    AND B.GROUP_ID = #{groupId}


    AND B.POSITION_ID = #{positionId}


    AND B.ORGAN_ID = #{organId}


    AND B.USER_ID = #{userId}


    AND (bue.ID_NAME LIKE concat('%',concat(#{key},'%'))
    OR bue.ID_MOBILE LIKE concat('%',concat(#{key},'%')))

SELECT DISTINCT bue.USER_ID,tm.MEMBER_ID,bue.ID_NAME AS NAME,bue.ID_MOBILE AS MOBILE FROM USER_RANGE_ORGAN B LEFT JOIN THIRD_MEMBER tm ON B.USER_ID = tm.USER_ID LEFT JOIN BASE_USER_EXT bue ON B.USER_ID = bue.USER_ID WHERE 1=1 AND B.ORGAN_ID = #{organId} AND B.GROUP_ID = #{groupId}
AND B.POSITION_ID IN
#{item}
AND (bue.ID_NAME LIKE concat('%',concat(#{q},'%')) OR bue.ID_MOBILE LIKE concat('%',concat(#{q},'%')))

SELECT B.RELATION_ID,
B.USER_ID,bue.ID_NAME AS NAME,
B.ORGAN_ID,org.NAME AS ORGAN_NAME,
B.FOREIGN_ID AS AREA_ID,GX.NAME AS AREA_NAME,
B.POSITION_ID,sp.NAME AS POSITION_NAME,
pg.GROUP_ID,pg.NAME AS GROUP_NAME
FROM USER_RANGE_ORGAN B
LEFT JOIN BASE_USER_EXT bue ON B.USER_ID = bue.USER_ID
LEFT JOIN BASE_ORGAN org ON B.ORGAN_ID = org.ORGAN_ID
LEFT JOIN BASE_XZQH GX ON B.FOREIGN_ID = GX.XZQH_ID
LEFT JOIN SYS_POSITION sp ON B.POSITION_ID = sp.POSITION_ID
LEFT JOIN PUBLIC_GROUP_POSITION pgP ON sp.POSITION_ID = pgP.POSITION_ID
LEFT JOIN PUBLIC_GROUP pg ON B.GROUP_ID = pg.GROUP_ID
WHERE 1 = 1 AND B.TYPE=30


    AND B.ORGAN_ID IN (select distinct(OW.ORGAN_ID) from ORGAN_WORK OW where

        OW.PARENT_ID = #{organwId}


        OW.SEARCH_CODE like CONCAT('%',CONCAT(#{organwId},'%'))

    )



    AND bue.ID_NAME LIKE concat('%',concat(#{name},'%'))


    AND bue.POST_CODE = #{postCode}


    AND org.NAME LIKE concat('%',concat(#{organName},'%'))


    AND B.USER_ID = #{userId}


    AND B.ORGAN_ID = #{organId}


    AND B.POSITION_ID = #{positionId}




            AND date_format(B.CREATE_TIME,'%Y-%m-%d') = #{createTime}




            AND to_char(B.CREATE_TIME,'YYYY-MM-DD')= #{createTime}




            AND to_char(B.CREATE_TIME,'YYYY-MM-DD')= #{createTime}




    AND B.GROUP_ID IN

        #{item}


ORDER BY B.CREATE_TIME DESC

SELECT B.RELATION_ID, B.USER_ID,bu.USERNAME,bue.ID_NAME AS NAME, bue.ID_MOBILE AS MOBILE, B.ORGAN_ID,org.NAME AS ORGAN_NAME FROM USER_RANGE_ORGAN B LEFT JOIN BASE_USER bu ON B.USER_ID = bu.USER_ID LEFT JOIN BASE_USER_EXT bue ON B.USER_ID = bue.USER_ID LEFT JOIN BASE_ORGAN org ON B.ORGAN_ID = org.ORGAN_ID LEFT JOIN ORGAN_WORK W on B.ORGAN_ID = W.ORGAN_ID LEFT JOIN ORGAN_WORK SOW on SOW.ORGANW_ID = #{organwId} WHERE 1 = 1 AND bue.NICKNAME is not null AND B.TYPE=10
AND bue.ID_NAME LIKE concat('%',concat(#{name},'%'))
AND W.PARENT_ID=#{organwId}
AND W.SEARCH_CODE like CONCAT('%',CONCAT(SOW.SEARCH_CODE,'%'))
AND org.NAME LIKE concat('%',concat(#{organName},'%'))
AND B.USER_ID = #{userId}
AND B.ORGAN_ID = #{organId}
AND (bue.ID_NAME LIKE concat('%',concat(#{q},'%')) OR bue.ID_MOBILE LIKE concat('%',concat(#{q},'%')) OR bu.MOBILE LIKE concat('%',concat(#{q},'%')) OR org.NAME LIKE concat('%',concat(#{q},'%')))
ORDER BY B.CREATE_TIME DESC

