SELECT DISTINCT bue.USER_ID,bue.ID_NAME AS NAME,bue.ID_MOBILE AS MOBILE, bue.KEYWORDS,B.ORGAN_ID,org.NAME AS ORGAN_NAME FROM USER_RANGE_ORGAN B LEFT JOIN BASE_USER_EXT bue ON B.USER_ID = bue.USER_ID LEFT JOIN BASE_ORGAN org ON B.ORGAN_ID = org.ORGAN_ID WHERE 1=1 AND bue.ID_NAME IS NOT NULL
AND B.ORGAN_ID = #{organId}
AND B.ORGAN_ID IN
#{item}
AND (bue.ID_NAME LIKE concat('%',concat(#{q},'%')) OR bue.ID_MOBILE LIKE concat('%',concat(#{q},'%')) OR bue.KEYWORDS LIKE concat('%',concat(#{q},'%')) )

SELECT * FROM SYS_POSITION B
where 1=1
  AND EXISTS (SELECT POSITION_ID FROM USER_RANGE_ORGAN C where B.POSITION_ID = C.POSITION_ID AND C.USER_ID = #{userId}
    )

SELECT B.*
FROM PUBLIC_GROUP B where GROUP_ID IN (
select DISTINCT(GROUP_ID) from PUBLIC_GROUP_POSITION PGP
LEFT JOIN USER_RANGE_ORGAN uro ON uro.POSITION_ID = PGP.POSITION_ID
LEFT JOIN SYS_ROLE_POSITION srp ON uro.POSITION_ID = srp.POSITION_ID
LEFT JOIN SYS_ROLE SR ON srp.ROLE_ID = SR.ROLE_ID
WHERE 1 = 1
and uro.USERL_ID = #{memberId}

    and SR.APP_ID = #{appId}


    and SR.ROLETYPE_ID in

        #{item}



    and B.GROUP_ID = #{groupId}


    and B.IS_DISABLED = #{isDisabled}


    and B.CODE = #{groupCode}

)
order by B.PRIORITY asc

SELECT M.* FROM (SELECT T.*, R.ROLE_ID FROM SYS_MENU T, SYS_ROLE_MENU R WHERE T.APP_ID = #{appId} AND T.TYPE = #{type} AND T.MENU_ID = R.MENU_ID) M, (SELECT distinct T.ROLE_ID FROM PUBLIC_GROUP T, USER_RANGE_ORGAN U WHERE T.GROUP_ID = U.GROUP_ID
and T.IS_DISABLED = #{isDisabled}
AND U.USERL_ID = #{memberId}) U WHERE M.ROLE_ID = U.ROLE_ID
AND M.IS_PROTECT = #{isProtect}
AND M.IS_PROTECT = 1
ORDER BY M.PRIORITY

SELECT distinct T.* FROM SYS_MENU T, SYS_ROLE_MENU R WHERE T.APP_ID = #{appId} AND T.TYPE = #{type} AND T.MENU_ID = R.MENU_ID AND T.DEL_FLAG = 0 AND R.ROLE_ID IN ( SELECT distinct T.ROLE_ID FROM PUBLIC_GROUP T, USER_RANGE_ORGAN U WHERE T.GROUP_ID = U.GROUP_ID
and T.IS_DISABLED = #{isDisabled}
AND U.USERL_ID = #{memberId} )
AND T.IS_PROTECT = #{isProtect}
AND T.IS_PROTECT = 1
ORDER BY T.PRIORITY

SELECT B.*
FROM PUBLIC_GROUP B
LEFT JOIN USER_RANGE_ORGAN uro ON B.GROUP_ID = uro.GROUP_ID
LEFT JOIN THIRD_MEMBER tm ON uro.USERL_ID = tm.MEMBER_ID
LEFT JOIN SYS_ROLE sr ON B.ROLE_ID = sr.ROLE_ID
WHERE 1 = 1

    and sr.APP_ID = #{appId}


    and sr.ROLETYPE_ID in

        #{item}



    and uro.USERL_ID = #{memberId}


    and B.GROUP_ID = #{groupId}


    and B.IS_DISABLED = #{isDisabled}


    and B.CODE = #{groupCode}

order by B.PRIORITY asc

SELECT B.*
FROM PUBLIC_GROUP B
LEFT JOIN SYS_ROLE sr ON B.ROLE_ID = sr.ROLE_ID
LEFT JOIN USER_RANGE_ORGAN uro ON B.GROUP_ID= uro.GROUP_ID
LEFT JOIN THIRD_MEMBER_TOKEN tmt ON tmt.MEMBER_ID= uro.USERL_ID
LEFT JOIN IDENTITY_ORGAN ideno ON B.GROUP_ID= ideno.GROUP_ID
WHERE 1=1

    and sr.APP_ID = #{appId}


    and sr.ROLETYPE_ID in

        #{item}



    and uro.USERL_ID = #{memberId}


    and B.GROUP_ID = #{groupId}


    AND tmt.SITE_ID = #{siteId}


    and B.IS_DISABLED = #{isDisabled}


    and B.CODE = #{groupCode}

order by B.PRIORITY asc

