WHERE B.IS_MEMBER = 1 and B.POWER = #{power}
  AND B.USERL_ID = #{memberId} and B.GROUP_ID = #{groupId}

SELECT distinct sr.ROLE_ID
FROM SYS_ROLE sr
LEFT JOIN PUBLIC_GROUP pb ON pb.ROLE_ID = sr.ROLE_ID
LEFT JOIN USER_RANGE_ORGAN uro ON pb.GROUP_ID = uro.GROUP_ID
LEFT JOIN THIRD_MEMBER tm ON uro.USERL_ID = tm.MEMBER_ID
WHERE 1 = 1

    and sr.APP_ID = #{appId}


    and sr.ROLETYPE_ID in

        #{item}



    and uro.USERL_ID = #{memberId}


    and pb.GROUP_ID = #{groupId}


    and pb.IS_DISABLED = #{isDisabled}


    and pb.CODE = #{groupCode}

order by sr.ROLE_ID asc

